"use strict";(self.webpackChunkchatgpt_shortcut=self.webpackChunkchatgpt_shortcut||[]).push([["49280"],{33731(e){e.exports=JSON.parse('{"id":9958,"title":"GitHub Release Notes","description":"\u57FA\u4E8E\u4ED3\u5E93\u3010\u6700\u8FD1\u4E00\u6B21\u6B63\u5F0F\u53D1\u5E03\u7684\u7248\u672C Tag\u3011\u4E0E\u3010\u5F53\u524D HEAD\u3011\u4E4B\u95F4\u7684\u5B9E\u9645\u4EE3\u7801\u5DEE\u5F02, \u751F\u6210\u53EF\u76F4\u63A5\u53D1\u5E03\u7684 GitHub Release Notes\u3002\\n\\n## \u53D6\u6570\uFF08\u5148\u505A,\u522B\u51ED\u5370\u8C61\uFF09\\n1. \u627E\u6700\u8FD1\u6B63\u5F0F\u7248 tag:`git describe --tags --abbrev=0`;\u82E5\u5B83\u662F pre-release (rc/beta/alpha)\u5219\u8DF3\u8FC7\u53D6\u4E0A\u4E00\u4E2A\u6B63\u5F0F tag;\u65E0 tag \u5219\u7528\u9996\u4E2A commit\u3002\\n2. \u5708\u8303\u56F4:`git log <tag>..HEAD --oneline` + `git diff <tag>..HEAD --stat`\u3002\\n3. \u6BCF\u7EC4\u6539\u52A8\u770B\u3010\u5B9E\u9645\u4EE3\u7801 diff\u3011\u4E0B\u7ED3\u8BBA,\u522B\u7167\u6284 commit \u6807\u9898\u2014\u2014message \u53EF\u80FD\u542B\u7CCA/\u8BEF\u5BFC,\u4EE5\u4EE3\u7801\u771F\u6B63\u6539\u4E86\u4EC0\u4E48\u4E3A\u51C6\u3002\\n\\n## \u6574\u7406\\n- \u5408\u5E76\u76F8\u4F3C/\u91CD\u590D\u63D0\u4EA4\u4E3A\u4E00\u6761\u3002\\n- \u5FFD\u7565\u4F4E\u4EF7\u503C:merge\u3001CI\u3001lint/\u683C\u5F0F\u5316\u3001\u7EAF\u6CE8\u91CA\u3001\u7248\u672C\u53F7 bump \u672C\u8EAB\u3002\\n- \u6309\u3010\u7528\u6237\u5F71\u54CD\u3011\u5F52\u7C7B,\u4E0D\u6309\u6587\u4EF6\u5F52\u7C7B\u3002\\n\\n## \u8F93\u51FA\u7ED3\u6784\uFF08\u6309\u6B64\u987A\u5E8F,\u7A7A\u7684\u5C0F\u8282\u7701\u7565\uFF09\\n\u9876\u90E8\u7ED9\u3010\u5EFA\u8BAE\u7248\u672C\u53F7\u3011:\u6309 semver \u5224\u7EA7(\u6709\u7834\u574F\u6027\u2192major\u3001\u6709\u65B0\u529F\u80FD\u2192minor\u3001\u4EC5\u4FEE\u590D/\u5185\u90E8\u2192patch),\u7ED9\u51FA\u5EFA\u8BAE tag + \u4E00\u53E5\u8BDD\u4E3B\u9898\u3002\\n\\n### \u26A0\uFE0F Breaking Changes\uFF08\u7834\u574F\u6027\u53D8\u66F4\u2014\u2014\u6709\u5219\u3010\u5FC5\u987B\u3011\u653E\u6700\u524D\u3001\u6700\u663E\u773C\uFF09\u6539\u4E86\u4EC0\u4E48 + \u4F7F\u7528\u8005\u8981\u600E\u4E48\u6539(\u8FC1\u79FB\u52A8\u4F5C)\u3002 \\n### \u2728 Features\uFF08\u7528\u6237\u80FD\u7528\u5230\u7684\u65B0\u529F\u80FD\uFF09 \\n### \u{1F41B} Bug Fixes\uFF08\u7528\u6237\u80FD\u611F\u77E5\u7684\u4FEE\u590D\uFF09 \\n### \u26A1 Performance\uFF08\u6027\u80FD/\u4F53\u79EF\uFF09 \\n### \u{1F527} Internal\uFF08\u5185\u90E8\u4F18\u5316/\u91CD\u6784,\u7528\u6237\u4E0D\u53EF\u89C1\u2014\u2014\u5E76\u6210\u7B80\u77ED\u4E00\u7EC4,\u4E0D\u5C55\u5F00\uFF09 \\n### \u{1F4E6} Dependencies\uFF08\u4F9D\u8D56\u5347\u7EA7,\u9010\u6761:\u5305\u540D \u65E7\u2192\u65B0\uFF09\\n\\n## \u5199\u6CD5\\n- \u6BCF\u6761\u4E00\u884C,\u4EE5\u3010\u7528\u6237\u89C6\u89D2\u7684\u5F71\u54CD\u3011\u5F00\u5934(\u80FD\u505A\u4EC0\u4E48/\u4FEE\u4E86\u4EC0\u4E48),\u4E0D\u662F\u5B9E\u73B0\u7EC6\u8282\u3002\\n- \u7B80\u6D01\u5177\u4F53:\u6709\u573A\u666F/\u6570\u5B57\u5C31\u5E26\u4E0A,\u4E0D\u5570\u55E6\u3002\u7528\u6237\u53EF\u89C1\u533A\u7528\u7528\u6237\u8BED\u8A00;Internal \u53EF\u6280\u672F\u5316\u4F46\u7B80\u77ED\u3002\\n\\n## \u53CC\u8BED & \u683C\u5F0F\\n\u4E2D\u3001\u82F1\u4E24\u7248,\u7ED3\u6784\u76F8\u540C\u2014\u2014\u4E0D\u662F\u9010\u5B57\u76F4\u8BD1,\u5404\u7528\u8BE5\u8BED\u8A00\u81EA\u7136\u7684 release-note \u53E3\u543B\u3002\\nGitHub Markdown,\u53EF\u76F4\u63A5\u7C98\u8D34\u53D1\u5E03:\u6807\u9898\u7528\u7248\u672C\u53F7,\u5C0F\u8282 ##/###,\u6761\u76EE\u7528 -\u3002","remark":"\u5BF9\u6BD4\u5F53\u524D\u4E0E\u4E0A\u4E00\u7248\u672C\u7684\u5DEE\u522B\uFF0C\u63D0\u4F9B\u7248\u672C\u66F4\u65B0\u8BF4\u660E","owner":"test","upvotes":1,"downvotes":0,"upvoteDifference":1,"updatedAt":"2026-06-08T11:42:15.755Z"}')}}]);